import { ChangeDetectionStrategy, Component, inject, signal } from '@angular/core';
import { takeUntilDestroyed } from '@angular/core/rxjs-interop';
import { ActivatedRoute } from '@angular/router';
import { catchError, EMPTY, switchMap } from 'rxjs';
import { ChatRoom } from '../../components/chat-room/chat-room';
import { ChatApi } from '../../services/chat-api';

@Component({
  selector: 'app-direct-chat',
  imports: [ChatRoom],
  templateUrl: './direct-chat.html',
  styleUrl: './direct-chat.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class DirectChat {
  private chatApi = inject(ChatApi);
  private route = inject(ActivatedRoute);
  chatRoomId = signal<number | undefined>(undefined);
  errorMessage = signal('');

  constructor() {
    this.route.paramMap.pipe(
      switchMap(params => {
        this.chatRoomId.set(undefined);
        this.errorMessage.set('');
        const userId = Number(params.get('userId'));

        if (!Number.isSafeInteger(userId) || userId <= 0) {
          this.errorMessage.set('Invalid user id.');
          return EMPTY;
        }

        return this.chatApi.getOrCreateDirectChat(userId).pipe(
          catchError(error => {
            console.error('Error loading direct chat room', error);
            this.errorMessage.set('Unable to load direct chat.');
            return EMPTY;
          }),
        );
      }),
      takeUntilDestroyed(),
    ).subscribe(({ chatRoomId }) => this.chatRoomId.set(chatRoomId));
  }
}
